    }
#  endif
#endif

  /* Configures the CPU clock, RTC slow and fast clocks, and performs
   * RTC slow clock calibration.
   */

  esp_clk_init();

  esp_mspi_pin_reserve();

  bootloader_init_mem();

#ifdef CONFIG_ESPRESSIF_SPIRAM_MEMTEST

